const VALID_MODES = ['uppercase', 'lowercase', 'slug'];

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function transform(text, mode) {
  switch (mode) {
    case 'uppercase': return text.toUpperCase();
    case 'lowercase': return text.toLowerCase();
    case 'slug': return slugify(text);
    default: throw new Error(`Unknown mode: ${mode}`);
  }
}

export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text using the specified mode (uppercase, lowercase, or slug).',
      inputSchema: {
        type: 'object',
