            type: 'string',
            enum: ['uppercase', 'lowercase', 'slug'],
            description: 'The transformation mode.',
          },
          trim: {
            type: 'boolean',
            default: true,
            description: 'Whether to trim whitespace from the input before transforming. Defaults to true.',
          },
        },
        required: ['text', 'mode'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { text, mode, trim = true } = args;

  if (typeof text !== 'string') {
    throw new Error('text is required and must be a string');
  }
  if (typeof mode !== 'string' || !VALID_MODES.includes(mode)) {
    throw new Error('mode is required and must be one of: uppercase, lowercase, slug');
