const VALID_MODES = ['uppercase', 'lowercase', 'slug'];
const ALLOWED_KEYS = ['text', 'mode', 'trim'];

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function transform(text, mode) {
  switch (mode) {
    case 'uppercase': return text.toUpperCase();
    case 'lowercase': return text.toLowerCase();
    case 'slug': return slugify(text);
    default: throw new Error(`Unknown mode: ${mode}`);
  }
}

export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text using the specified mode (uppercase, lowercase, or slug).',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'The text to transform.' },
          mode: {
            type: 'string',
            enum: ['uppercase', 'lowercase', 'slug'],
            description: 'The transformation mode.',
          },
          trim: {
            type: 'boolean',
            default: true,
            description: 'Whether to trim whitespace from the input before transforming. Defaults to true.',
          },
        },
        required: ['text', 'mode'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { text, mode, trim = true } = args;

  const extraKeys = Object.keys(args).filter((k) => !ALLOWED_KEYS.includes(k));
  if (extraKeys.length > 0) {
    throw new Error(`Unexpected properties: ${extraKeys.join(', ')}`);
  }

  if (typeof text !== 'string') {
    throw new Error('text is required and must be a string');
  }
  if (typeof mode !== 'string' || !VALID_MODES.includes(mode)) {
    throw new Error('mode is required and must be one of: uppercase, lowercase, slug');
  }
  if (trim !== undefined && typeof trim !== 'boolean') {
    throw new Error('trim must be a boolean');
  }

  const working = trim ? text.trim() : text;
  const result = transform(working, mode);

  return {
    content: [{ type: 'text', text: result }],
  };
}

